   795→public(package) fun borrow_flash_loan<MarketType, CoinType>(
   796→    self: &mut Market<MarketType>,
   797→    emode_group: u8,
   798→    amount: u64,
   799→    ctx: &mut TxContext,
   800→): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
   801→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   802→
   803→    assert!(!asset.flash_loan_paused(), error::flash_loan_paused_for_asset());
   804→    assert!(!asset.flash_loan_ongoing(), error::flash_loan_ongoing());
   805→
   806→    asset.flash_loan_triggered<MarketType>();
   807→
   808→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   809→
   810→    let emode = self.emode_group_registry.borrow_emode_group(emode_group).borrow_emode(type_name::with_defining_ids<CoinType>());
   811→    let flash_loan_fee_rate = emode.flash_loan().fee_rate();
   812→
   813→    let fee = flash_loan_fee_rate.int_mul(amount);
   814→    assert!(fee != 0, error::reserve_flash_loan_fee_too_small());
   815→
   816→    let (balance, inner) = reserve.borrow_flash_loan(amount);
   817→    (balance.into_coin(ctx), FlashLoan<MarketType, CoinType> { inner, fee })
   818→}
   819→
   820→public(package) fun repay_flash_loan<MarketType, CoinType>(
   821→    self: &mut Market<MarketType>,
   822→
   823→    mut coin: Coin<CoinType>,
   824→    loan: FlashLoan<MarketType, CoinType>,
   825→
   826→    referral: &mut protocol::referral::Referral,
   827→    mut maybe_referral_code: Option<String>,
   828→
   829→    ctx: &mut TxContext
   830→) {
   831→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   832→
   833→    assert!(asset.flash_loan_ongoing(), error::flash_loan_not_ongoing());
   834→    asset.flash_loan_finished<MarketType>();
   835→
   836→    let FlashLoan { inner, fee } = loan;
   837→    assert!(coin.value() == inner.amount() + fee, error::reserve_flash_loan_not_paid_enough());
   838→
   839→    let mut fee_coin = coin.split(fee, ctx);
   840→
   841→    if (maybe_referral_code.is_some()) {
   842→        let referral_code = maybe_referral_code.extract();
   843→        fee_coin = referral.track_flash_loan_usage(
   844→            fee_coin,
   845→            referral_code,
   846→            ctx.sender(),
   847→            ctx,
   848→        );
   849→        
   850→        // no free ride after rebate
   851→        assert!(fee_coin.value() != 0, error::reserve_flash_loan_fee_too_small());
   852→    };
   853→
   854→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   855→    reserve.repay_flash_loan(inner, coin, fee_coin);
   856→}
   857→
   858→fun refresh_obligation_assets_interest<MarketType>(
   859→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   860→    emode_group: &EModeGroup,
   861→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   862→    obligation: &mut Obligation<MarketType>,
   863→    now: u64,
   864→) {
   865→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   866→
   867→    // collateral
   868→    let asset_types = obligation.deposit_types();
   869→
   870→    let (mut i, n) = (0, asset_types.length());
   871→
   872→    while (i < n) {
   873→        let name = asset_types[i];
   874→
   875→        let asset = assets.load_by_type(name);
   876→        let collateral_settings = emode_group.borrow_emode(name).collateral();
   877→
   878→        // update index first, since it's not used after this point
   879→        i = i + 1;
   880→
   881→        // cannot be collateral, ignore
   882→        if (!collateral_settings.can_be_collateral()) { continue };
   883→
   884→        accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
   885→    };
   886→}
   887→
   888→fun refresh_obligation_borrow_interest_with_new_borrow<MarketType>(
   889→    maybe_new_borrow_coin_type: TypeName,
   890→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   891→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   892→    obligation: &mut Obligation<MarketType>,
   893→    now: u64,
   894→) {
   895→
   896→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   897→
   898→    if (obligation.has_debt(maybe_new_borrow_coin_type)) { return };
   899→
   900→    let asset = assets.load_by_type(maybe_new_borrow_coin_type);
   901→    accrue_interest(maybe_new_borrow_coin_type, reserves, asset.asset_config(), asset.interest_model(), now);
   902→}
   903→
   904→fun refresh_obligation_borrow_interest<MarketType>(
   905→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   906→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   907→    obligation: &mut Obligation<MarketType>,
   908→    now: u64,
   909→) {
   910→    let asset_types = obligation.debt_types();
   911→
   912→    let (mut i, n) = (0, asset_types.length());
   913→
   914→    while (i < n) {
   915→        let name = asset_types[i];
   916→
   917→        let asset = assets.load_by_type(name);
   918→
   919→        let reserve = accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
   920→        obligation.accrue_interest(name, reserve.borrow_index().value());
   921→
   922→        i = i + 1;
   923→    };
   924→}
